rm *.sac > /dev/null
nm=$(cat ../stationsSH.info | wc -l)
cat ../stationsSH.info | gawk -v txtb="$txtloc" -v nn="$nm" '{if (NR<=nn) print $1,$2,$3,$4,$5}' > sta_dist_az_rev
sed -i 's/data\///g' sta_dist_az_rev
sed -i 's/\.\.t//g' sta_dist_az_rev
gawk -v txtb="$txtloc" -v nn="$nm"  'BEGIN{for (i=1;i<=nn;i++) printf("%04d \n",i-1)}' > temp
cp ../waveforms/SH*_0???.sac .
cat sta_dist_az_rev | gawk '{print $1}' | gawk 'BEGIN{FS="[.]"} {print $1"."$2}' > sta1temp
cat temp | gawk '{print "SH_syn_"$1".sac 0 0"}' > list1
cat temp | gawk '{print "SH_obs_"$1".sac 0 0"}' > list2
paste sta_dist_az_rev list1 list2 sta1temp | sort -nk3  > allinfo
bt=$(cat ../Par.file | gawk '{if (NR==1) print $2}')
echo  "r *.sac\nch b ${bt}\nch t1 0\nch dist 5000\nch delta 1\nw over\nq\n" | sac
nrow1=$(cat allinfo| wc -l | gawk '{a=$1;b=$1%3;c=a-b+3;d=c/3;print d;}')
nrow2=$(cat allinfo| wc -l | gawk '{a=$1;b=$1%3;c=a-b+3;d=c/3;print d;}')
nrow3=$(cat allinfo| wc -l | gawk '{a=$1;b=$1%3;c=a-b+3;d=c/3;print a-d-d;}')
dy=$(echo $nrow1 | gawk '{print 10/$1}')
tb=$(cat ../Par.file | gawk '{if (NR==3) print $2+7.5}')
te=$(cat ../Par.file | gawk '{if (NR==4) print $2-7.5}')
txtloc=$(echo $tb | gawk '{print $1-5}')
am=$(saclst depmax f *.sac | minmax | gawk 'BEGIN{FS="[</>]"} {print $8*3}')
cat allinfo | gawk '{print $6,$7,0}' | gawk -v txtb="$txtloc" -v nrow1="$nrow1" -v dy="$dy" -v tb="$tb" -v te="$te" -v am="$am" '{if (NR<=nrow1) {if (NR==1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow1+1" -JX2i/9.9i -X0.8i -Y1i -P -K  -Ent1 -W1.5p/255/0/0 -M"am"/0 > map.ps << EOF"; print $1,$2,nrow1-NR+1; print "EOF";} if (NR>1&&NR<nrow1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow1+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/255/0/0 -M"am"/0  >> map.ps << EOF"; print $1,$2,nrow1-NR+1; print "EOF";} if (NR==nrow1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow1+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/255/0/0 -M"am"/0 -Ba20f10/S >> map.ps << EOF"; print $1,$2,nrow1-NR+1; print "EOF";}}}'  | sh > /dev/null
cat allinfo | gawk '{print $9,$10,$12,$2,$3}' | gawk -v txtb="$txtloc" -v nrow1="$nrow1" -v dy="$dy" -v tb="$tb" -v te="$te" -v am="$am" '{if (NR<=nrow1) {if (NR==1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow1+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0 >> map.ps << EOF"; print $1,$2,nrow1-NR+1; print "EOF"; print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1-NR+0.8,$5,$4);print "EOF";} if (NR>1&&NR<nrow1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow1+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0  >> map.ps << EOF"; print $1,$2,nrow1-NR+1; print "EOF";print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1-NR+0.8,$5,$4);print "EOF";} if (NR==nrow1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow1+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0  >> map.ps << EOF"; print $1,$2,nrow1-NR+1; print "EOF";print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1-NR+0.8,$5,$4);print "EOF";}}}'| sh  > /dev/null


cat allinfo | gawk '{print $6,$7,0}' | gawk -v txtb="$txtloc" -v nrow1="$nrow1" -v nrow2="$nrow2" -v dy="$dy" -v tb="$tb" -v te="$te" -v am="$am" '{if (NR>nrow1&&NR<=nrow1+nrow2) {if (NR==nrow1+1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow2+1" -JX2i/9.9i -X2.4i  -P -K -O -Ent1 -W1.5p/255/0/0 -M"am"/0 >> map.ps << EOF"; print $1,$2,nrow1+nrow2-NR+1; print "EOF";} if (NR>nrow1+1&&NR<nrow1+nrow2) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow2+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/255/0/0 -M"am"/0  >> map.ps << EOF"; print $1,$2,nrow1+nrow2-NR+1; print "EOF";} if (NR==nrow1+nrow2) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow2+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/255/0/0 -M"am"/0 -Ba20f10/S >> map.ps << EOF"; print $1,$2,nrow1+nrow2-NR+1; print "EOF";}}}' | sh  > /dev/null
cat allinfo | gawk '{print $9,$10,$12,$2,$3}' | gawk -v txtb="$txtloc" -v nrow1="$nrow1" -v nrow2="$nrow2" -v dy="$dy" -v tb="$tb" -v te="$te" -v am="$am" '{if (NR>nrow1&&NR<=nrow1+nrow2) {if (NR==nrow1+1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow2+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0 >> map.ps << EOF"; print $1,$2,nrow1+nrow2-NR+1; print "EOF";print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1+nrow2-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1+nrow2-NR+0.8,$5,$4);print "EOF";} if (NR>nrow1+1&&NR<nrow1+nrow2) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow2+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0  >> map.ps << EOF"; print $1,$2,nrow1+nrow2-NR+1; print "EOF";print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1+nrow2-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1+nrow2-NR+0.8,$5,$4);print "EOF";} if (NR==nrow1+nrow2) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow2+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0 >> map.ps << EOF"; print $1,$2,nrow1+nrow2-NR+1; print "EOF";print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1+nrow2-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1+nrow2-NR+0.8,$5,$4);print "EOF";}}}' | sh   > /dev/null
cat allinfo | gawk '{print $6,$7,0}' | gawk -v txtb="$txtloc" -v nrow1="$nrow1" -v nrow2="$nrow2"  -v nrow3="$nrow3" -v dy="$dy" -v tb="$tb" -v te="$te" -v am="$am" '{if (NR>nrow1+nrow2&&NR<=nrow1+nrow2+nrow3) {if (NR==nrow1+nrow2+1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow3+1" -JX2i/9.9i -X2.4i  -P -K -O -Ent1 -W1.5p/255/0/0 -M"am"/0 >> map.ps << EOF"; print $1,$2,nrow1+nrow2+nrow3-NR+1; print "EOF";} if (NR>nrow1+nrow2+1&&NR<nrow1+nrow2+nrow3) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow3+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/255/0/0 -M"am"/0  >> map.ps << EOF"; print $1,$2,nrow1+nrow2+nrow3-NR+1; print "EOF";} if (NR==nrow1+nrow2+nrow3) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow3+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/255/0/0 -M"am"/0 -Ba20f10/S >> map.ps << EOF"; print $1,$2,nrow1+nrow2+nrow3-NR+1; print "EOF";}}}' | sh  > /dev/null
cat allinfo | gawk '{print $9,$10,$12,$2,$3}' | gawk -v txtb="$txtloc" -v nrow1="$nrow1" -v nrow2="$nrow2"  -v nrow3="$nrow3" -v dy="$dy" -v tb="$tb" -v te="$te" -v am="$am" '{if (NR>nrow1+nrow2&&NR<=nrow1+nrow2+nrow3) {if (NR==nrow1+nrow2+1) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow3+1" -JX2i/9.9i  -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0 >> map.ps << EOF"; print $1,$2,nrow1+nrow2+nrow3-NR+1; print "EOF";print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1+nrow2+nrow3-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1+nrow2+nrow3-NR+0.8,$5,$4);print "EOF";} if (NR>nrow1+nrow2+1&&NR<nrow1+nrow2+nrow3) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow3+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0  >> map.ps << EOF"; print $1,$2,nrow1+nrow2+nrow3-NR+1; print "EOF";print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1+nrow2+nrow3-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1+nrow2+nrow3-NR+0.8,$5,$4);print "EOF";} if (NR==nrow1+nrow2+nrow3) {print "pssac2 -C-30/310 -R"tb"/"te"/0/"nrow3+1" -JX2i/9.9i -P -K -O -Ent1 -W1.5p/0/0/0 -M"am"/0 >> map.ps << EOF"; print $1,$2,nrow1+nrow2+nrow3-NR+1; print "EOF";print "pstext -N -R -J -P -K -O >> map.ps << EOF"; print txtb,nrow1+nrow2+nrow3-NR+1.2" 10 0 1 ML "$3;printf (txtb" %f 10 0 0 ML %.1f\260 %.1f\260\n",nrow1+nrow2+nrow3-NR+0.8,$5,$4);print "EOF";}}}' | sh  > /dev/null
